  "recovered_c": "uint64_t fn_14(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (out_cap < len) {\n    return VERA_ERR;\n  }\n\n  size_t i;\n  for (i = 0; i < len; i += 3) {\n    uint32_t value = (i + 2 < len ? (uint32_t)in[i + 2] << 16 : 0) | (i + 1 < len ? (uint32_t)in[i + 1] << 8 : 0) | in[i];\n    out[i * 4 / 3] = 'AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B'[(value & 0x3f)];\n    if (i + 1 < len) {\n      out[i * 4 / 3 + 1] = 'AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B'[(value | (uint32_t)in[i + 1] << 0x10) >> 6 & 0x3f];\n      if (i + 2 < len) {\n        out[i * 4 / 3 + 2] = 'AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B'[(value >> 0xc) & 0x3f];\n      }\n    }\n  }\n\n  if (len % 3 == 1) {\n    out[len * 4 / 3] = 'AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B'[(in[len - 1] & 3) << 4];\n    out[len * 4 / 3 + 1] = 'AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B'[(in[len - 1] >> 2)];\n    out[len * 4 / 3 + 2] = '=';\n  } else if (len % 3 == 2) {\n    out[len * 4 / 3] = 'AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B'[(in[len - 2] & 0xf00) >> 6];\n    out[len * 4 / 3 + 1] = 'AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B'[(in[len - 2] | (uint32_t)in[len - 1] << 0x10) >> 0xc & 0x3f];\n    out[len * 4 / 3 + 2] = 'AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B'[(in[len - 1] >> 2)];\n    out[len * 4 / 3 + 3] = '=';\n  }\n\n  return len * 4 / 3;\n}"
